'use strict';
const budget='root = App([budget, choice])\nbudget = Budget("room", "房间焕新预算", "¥", 5000, [paint, light])\npaint = CostItem("paint", "墙面涂料", 280, 3, "桶")\nlight = CostItem("light", "灯具", 420, 2, "盏")\nchoice = Choice("finish", "墙面效果", [matte, gloss], "matte")\nmatte = Option("matte", "哑光", "柔和低反光")\ngloss = Option("gloss", "亮面", "明亮易清洁")';
const trip='root = App([trip])\ntrip = Trip("sf", [ferry, tower, park], [])\nferry = Place("ferry", "渡轮大厦", 37.7955, -122.3937, "旧金山滨水地标", "", "")\ntower = Place("tower", "科伊特塔", 37.8024, -122.4058, "电报山上的城市观景点", "", "")\npark = Place("park", "华盛顿广场", 37.8008, -122.4102, "北滩街区的公园", "", "")';
const dashboard='root = App([stack, form])\nstack = Stack("row", [table, chart])\ntable = Table("方案对比", ["方案", "月费", "响应"], [["基础", "¥99", "120 ms"], ["专业", "¥299", "85 ms"]])\nchart = Chart("响应时间", "bar", ["基础", "专业"], [120, 85], "ms")\nform = Form("intake", "项目信息", [name, tier, budget, notes])\nname = Field("name", "项目名称", "text", "例如：官网改版", true, [], "", "")\ntier = Field("tier", "方案", "select", "", true, ["基础", "专业"], "", "基础")\nbudget = Field("budget", "预算", "number", "10000", false, [], "元", "10000")\nnotes = Field("notes", "备注", "textarea", "", false, [], "", "")';
module.exports={budget,trip,dashboard};
